<?php
/** Pages editorial workspace: independent working/public snapshots, shared core editor/media picker and explicit publication controls. */
declare(strict_types=1);
use DBLESSCMS\{PagePublications,PageBlueprints,JsonStore,Icons,ContentDocuments,ContentContext};
use function DBLESSCMS\e;
$repository=new PagePublications($context->store);$catalog=$repository->read();$isNew=$route==='new';$row=$isNew?null:$repository->record($key);$siteRevision=$context->store->read('site')['revision'];$sourceRevision=$isNew||isset($catalog['data']['records'][$key])?'':$context->store->read($key,null,true)['revision'];
/** Emit common CSRF/catalog/site/legacy-source fields; receives action, returns nothing, output values are escaped and no state is changed. */
$fields=static function()use($csrf,$catalog,$siteRevision,$sourceRevision,$key):void{foreach(['csrf_token'=>$csrf,'catalog_revision'=>$catalog['revision'],'site_revision'=>$siteRevision,'source_revision'=>$sourceRevision,'key'=>$key] as $name=>$value)echo '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';};
/** Render a canonical icon submit with translated accessible name; receives action, returns safe HTML only. */
$submit=static fn(string $action):string=>'<button type="submit" class="icon-button" title="'.e($t('pages.action.'.$action)).'" aria-label="'.e($t('pages.action.'.$action)).'">'.Icons::svg(match($action){'save'=>'confirm','publish'=>'activate','unpublish'=>'deactivate','schedule'=>'history','duplicate'=>'pages','restore'=>'restore',default=>'confirm'},$context->base).'</button>';
?>
<?php if($isNew): ?>
<form method="post" action="<?= e($context->url('editorial-create')) ?>" data-pages-form class="panel stack"><?php $fields(); ?>
<h2><?= e($t('pages.createModel')) ?></h2><div class="field-grid"><label><?= e($t('pages.editorialTitle')) ?><input name="title" maxlength="200" required data-pages-title></label><label><?= e($t('pages.slug')) ?><input name="slug" maxlength="64" pattern="[a-z0-9][a-z0-9\-]{0,63}" required data-pages-slug></label><label><?= e($t('pages.model')) ?><select name="model"><?php foreach(PageBlueprints::names() as $model): ?><option value="<?= e($model) ?>"><?= e($t('pages.model.'.$model)) ?></option><?php endforeach; ?></select></label><label><?= e($t('pages.parent')) ?><select name="parent"><option value=""><?= e($t('pages.noParent')) ?></option><?php foreach($pages as $id=>$item): if(!PagePublications::identifier((string)$id))continue; ?><option value="<?= e($id) ?>"><?= e($item['data']['meta']['title']) ?></option><?php endforeach; ?></select></label></div><p><?= e($t('pages.modelHelp')) ?></p><div class="savebar"><?= $submit('save') ?></div></form>
<?php else: $snapshot=$row['draft'];$pageDocument=$snapshot['document'];$effective=PagePublications::effective($row);$markupDefinition=$pageDocument['markup']??['html'=>'','bindings'=>[]];$markupPageKey=$key; ?>
<section class="panel"><div class="row-actions"><strong><?= e($t('pages.state.'.PagePublications::status($row))) ?></strong><a class="icon-button" title="<?= e($t('pages.preview_action',['name'=>$pageDocument['meta']['title']])) ?>" aria-label="<?= e($t('pages.preview_action',['name'=>$pageDocument['meta']['title']])) ?>" href="<?= e($link('preview',$key)) ?>" target="_blank" rel="noopener noreferrer"><?= Icons::svg('preview',$context->base) ?></a></div><p><?= e($t('pages.draftHelp')) ?></p></section>
<form method="post" action="<?= e($context->url('editorial-save')) ?>" data-pages-form data-page-markup-form class="stack"><?php $fields(); ?><input type="hidden" name="page_status" value="draft"><input type="hidden" name="meta_keywords" value="<?= e($pageDocument['meta']['keywords']) ?>">
<section class="panel"><h2><?= e($t('pages.content')) ?></h2><div class="field-grid"><?php foreach(['title','description','image','imageAlt'] as $field): ?><label><?= e($t('pages.meta_'.$field)) ?><?php if($field==='description'): ?><textarea name="meta_description" maxlength="500" rows="3"><?= e($pageDocument['meta'][$field]) ?></textarea><?php else: ?><input name="meta_<?= e($field) ?>" maxlength="<?= $field==='title'?200:2048 ?>" <?= $field==='title'?'required':'' ?> <?= $field==='image'?'data-media-field="image"':'' ?> value="<?= e($pageDocument['meta'][$field]) ?>"><?php endif; ?></label><?php endforeach; ?></div></section>
<details class="panel" open><summary><?= e($t('pages.layoutData')) ?></summary><label class="editor-checkbox"><input type="checkbox" name="markup_enabled" value="1" <?= isset($pageDocument['markup'])?'checked':'' ?>><?= e($t('pages.authored')) ?></label><p><?= e($t('pages.nativePreserved')) ?></p><?php require $context->config->root.'/admin/markup-editor.php'; ?><details><summary><?= e($t('pages.native')) ?></summary><?php $slideLocations=\DBLESSCMS\Slides::locations($context->store->templates->get($context->store->read('site')['data']['template']));require __DIR__.'/native-slides.php'; ?><textarea data-native-content name="native_content" rows="8" spellcheck="false"><?= e(JsonStore::encode($pageDocument['content'])) ?></textarea></details></details>
<details class="panel"><summary><?= e($t('pages.structure')) ?></summary><div class="field-grid"><label><?= e($t('pages.slug')) ?><input name="slug" maxlength="64" pattern="[a-z0-9][a-z0-9\-]{0,63}" value="<?= e($snapshot['url']) ?>" required></label><label><?= e($t('pages.parent')) ?><select name="parent"><option value=""><?= e($t('pages.noParent')) ?></option><?php foreach($pages as $id=>$item): if((string)$id===$key||!PagePublications::identifier((string)$id))continue; ?><option value="<?= e($id) ?>" <?= $row['parent']===(string)$id?'selected':'' ?>><?= e($item['data']['meta']['title']) ?></option><?php endforeach; ?></select></label></div><p><?= e($t('pages.urlHelp')) ?></p><small><?= e($key) ?></small></details>
<details class="panel"><summary><?= e($t('pages.seo')) ?></summary><p><?= e($t('pages.inheritance')) ?></p><div class="field-grid"><?php foreach($snapshot['seo'] as $field=>$value): ?><label><?= e($t('pages.seo.'.$field)) ?><input name="seo_<?= e($field) ?>" <?= $field==='noindex'?'type="checkbox" value="1" '.($value?'checked':''):'maxlength="2048" value="'.e($value).'"' ?> <?= $field==='socialImage'?'data-media-field="image"':'' ?>></label><?php endforeach; ?></div><div class="notice" data-seo-preview><strong><?= e($snapshot['seo']['title']?:$pageDocument['meta']['title']) ?></strong><p><?= e($snapshot['seo']['description']?:$pageDocument['meta']['description']) ?></p><small><?= e($t('pages.previewIllustrative')) ?></small></div></details>
<div class="savebar"><span><?= e($t('pages.saveDraft')) ?></span><?= $submit('save') ?></div></form>
<section class="panel"><h2><?= e($t('pages.publication')) ?></h2><p><?= e($t('pages.publishSaved')) ?></p><div class="row-actions"><?php foreach(['publish','unpublish'] as $action): ?><form method="post" action="<?= e($context->url('editorial-'.$action)) ?>" data-pages-form><?php $fields(); ?><?= $submit($action) ?></form><?php endforeach; ?></div><form method="post" action="<?= e($context->url('editorial-schedule')) ?>" data-pages-form><?php $fields(); ?><label><?= e($t('pages.scheduleUTC')) ?><input name="publish_at" type="datetime-local" required></label><?= $submit('schedule') ?></form><details><summary><?= e($t('pages.action.duplicate')) ?></summary><form method="post" action="<?= e($context->url('editorial-duplicate')) ?>" data-pages-form><?php $fields(); ?><label><?= e($t('pages.slug')) ?><input name="slug" required maxlength="64" pattern="[a-z0-9][a-z0-9\-]{0,63}"></label><?= $submit('duplicate') ?></form></details></section>
<section class="panel"><h2><?= e($t('nav.history')) ?></h2><?php foreach($repository->history($key) as $backup=>$entry): ?><details><summary><?= e($entry['at'].' · '.$t('pages.action.'.$entry['action'])) ?></summary><p><?= e($t('pages.restoreDraftHelp')) ?></p><pre class="json-editor"><?= e(JsonStore::encode(['before'=>$entry['record']['draft'],'current'=>$snapshot])) ?></pre><form method="post" action="<?= e($context->url('editorial-restore')) ?>" data-pages-form><?php $fields(); ?><input type="hidden" name="backup" value="<?= e($backup) ?>"><?= $submit('restore') ?></form></details><?php endforeach; ?></section>
<?php endif; ?>
